        function F_abort(app)
            switch app.projectData.gui_data.calib_mode
                case 0
                    app.logERR('mode NONE')
                    app.GUI_displayWarn('ERROR', 'mode NONE')
                    return
                case 1
                    app.logDBG('mode HAND')
                    app.GUI_displayWarn('ERROR', 'MODE HAND NOT IMPLEMENTED!')
                    return
                case 2
                    app.logDBG('mode ROBOT')
                    app.ROS_abort();
                otherwise
                    app.logERR(['Invalid calibration mode!' num2str(app.projectData.gui_data.calib_mode)])
                    app.GUI_displayWarn('ERROR', ['Invalid calibration mode!' num2str(app.projectData.gui_data.calib_mode)])
                return
            end
        end

        function [reinit_needed,b_finish] = F_increment_calib_index(app)
            reinit_needed = false;
            b_finish = false;

            if app.projectData.robot_calib_data.i_theta > length(app.projectData.robot_calib_data.theta_v)
                b_finish = true;
                app.GUI_displayWarn("END","NO MORE POINTS...", false);
                app.logINFO("F_increment_calib_index - END");
                return;
            end

            app.projectData.robot_calib_data.i_wrench = app.projectData.robot_calib_data.i_wrench + 1;
            if app.projectData.robot_calib_data.i_wrench > size(app.projectData.robot_calib_data.wrench_v{app.projectData.robot_calib_data.i_fn},2)
                reinit_needed = true; % <- needs to dismiss the contact
                app.projectData.robot_calib_data.i_wrench = 1;
                app.projectData.robot_calib_data.i_fn = app.projectData.robot_calib_data.i_fn + 1;
                if app.projectData.robot_calib_data.i_fn > length(app.projectData.robot_calib_data.fn_v)
                    app.projectData.robot_calib_data.i_fn = 1;
                    app.projectData.robot_calib_data.i_phi = app.projectData.robot_calib_data.i_phi + 1;
                    if app.projectData.robot_calib_data.i_phi > length(app.projectData.robot_calib_data.phi_v)
                        app.projectData.robot_calib_data.i_phi = 1;
                        app.projectData.robot_calib_data.i_theta = app.projectData.robot_calib_data.i_theta + 1;
                        if app.projectData.robot_calib_data.i_theta > length(app.projectData.robot_calib_data.theta_v)
                            b_finish = true;
                            app.saveProject();
                            app.GUI_displayWarn("END","NO MORE POINTS...", false);
                            app.logINFO("F_increment_calib_index - END");
                            return;
                        end
                    end
                end
            end
            % SPECIAL CASE: wrench_v is empty
            if isempty(app.projectData.robot_calib_data.wrench_v{app.projectData.robot_calib_data.i_fn})
                app.logWARN("wrench_v is empty");
                app.F_increment_calib_index();
                return;
            end
            theta = app.projectData.robot_calib_data.theta_v(app.projectData.robot_calib_data.i_theta);
            phi = app.projectData.robot_calib_data.phi_v(app.projectData.robot_calib_data.i_phi);
            if (theta == 0) && (phi~=0)
                app.logWARN("theta=0 and phi!=0");
                app.projectData.robot_calib_data.i_wrench = 1;
                app.projectData.robot_calib_data.i_fn = 1;
                app.projectData.robot_calib_data.i_phi = 1;
                app.projectData.robot_calib_data.i_theta = app.projectData.robot_calib_data.i_theta + 1;
            end
        end


        function F_receiveCalibData( app,...
                update_gui, ...
                time_wrench,wrench,...
                time_tactile_raw,tactile_raw,...
                time_tactile_rect,tactile_rect,...
                time_pose, pose)
            % Receive a calib data sample
            % check if sample is good
            % update the gui and store the sample

            if app.projectData.gui_data.calib_mode == 1 %MODE_HAND
                % check the minimum fz
                if abs(wrench(3)) < app.projectData.gui_data.min_fz
                    return; %do not consider the sample
                end
            end

            % if fn too high discard sample
            if abs(wrench(3)) >  app.projectData.calib_data.fn_intervals(end)
                return; %fn too high
            end

            %compute centroid
            if app.projectData.gui_data.calib_mode == 1 %MODE_HAND
                centroid = compute_centroid( ...
                    tactile_rect,...
                    app.projectData.finger_info.taxels_x_coords,...
                    app.projectData.finger_info.taxels_y_coords,...
                    app.projectData.finger_info.broken_cells);
            else
                centroid = pose(1:2);
            end

            %find zone index
            zone_index = find_geometric_zone(...
                centroid,...
                app.projectData.calib_data.zone_angle_bound_lines, ...
                app.projectData.calib_data.zone_radius_intervals);

            %if invlaid zone discard sample
            if isnan(zone_index)
                return; %bad zone
            end

            %if here I have to save the point

            %find fn index
            fn_index = find_interval(app.projectData.calib_data.fn_intervals,abs(wrench(3)));

            %compute the plot point
            wrench_plot_point = compute_wrench_plot_point(...
                wrench,...
                app.dependent_data.fn_intervals_centers(fn_index),...
                app.dependent_data.zone_central_transforms{zone_index},...
                app.projectData.calib_data.plot_data.mu,...
                app.projectData.calib_data.plot_data.alpha,...
                app.projectData.calib_data.plot_data.gamma...
            );

            %Save point
            app.projectData.calib_data.time_voltage_rect_cell{zone_index,fn_index}(:,end+1) = time_tactile_rect;
            app.projectData.calib_data.voltage_rect_cell{zone_index,fn_index}(:,end+1) = tactile_rect;

            app.projectData.calib_data.time_voltage_raw_cell{zone_index,fn_index}(:,end+1) = time_tactile_raw;
            app.projectData.calib_data.voltage_raw_cell{zone_index,fn_index}(:,end+1) = tactile_raw;

            app.projectData.calib_data.time_wrench_cell{zone_index,fn_index}(:,end+1) = time_wrench;
            app.projectData.calib_data.wrench_cell{zone_index,fn_index}(:,end+1) = wrench;

            app.projectData.calib_data.time_pose_cell{zone_index,fn_index}(:,end+1) = time_pose;
            app.projectData.calib_data.pose_cell{zone_index,fn_index}(:,end+1) = pose;

            app.projectData.calib_data.plot_data.wrench_plot_cell{zone_index,fn_index}(:,end+1) = wrench_plot_point;

            %Update visual-single point
            b_sample_in_view = zone_index == app.dropDown_zone.Value.index && fn_index == app.dropDown_fn_interval.Value.index;
            if update_gui
                b_plot = app.slider_plot_radius.Value == 0 || (sqrt( sum(wrench_plot_point.^2)  ) < app.slider_plot_radius.Value);
                b_plot = b_plot && b_sample_in_view;
                if  b_plot
                    app.GUI_plotSingleSample(wrench_plot_point);  
                end
            end
            app.GUI_plotCentroid(centroid,zone_index);

            if b_sample_in_view
                app.label_this_samples.Text = num2str( str2double(app.label_this_samples.Text) +1 );
            end
            app.label_tot_samples.Text = num2str( str2double(app.label_tot_samples.Text) +1 );

        end

    end


    % Callbacks that handle component events
    methods (Access = private)

        % Code that executes after component creation
        function startupFcn(app)
            %Set the LOG LEVEL
            app.log_level = 2; %INFO
            app.logINFO("Start");
            %First update the matlab path
            app.updatePath();
            %Clear everithing except the log
            app.GUI_clearAll();
            app.logDBG("Start END");
        end

        % Close request function: FingerCalibrationUIFigure
        function FingerCalibrationUIFigureCloseRequest(app, event)

            if ~app.GUI_displayWarnYN('Close', 'Close the app, are you sure?')
                return
            end

            % TODO Clear stuff!
            % ROS stuff, timers, and vars
            app.ROS_clear();

            if ~isempty(app.called_app)
                delete(app.called_app)
            end

            delete(app)
        end

        % Menu selected function: NewMenu
        function NewMenuSelected(app, event)
            % File->New...
            % Ask for the new file location
            app.logDBG("NewMenuSelected...");
            if ~isempty(app.projectData)
                app.logDBG("Project Present");
                if ~app.GUI_displayWarnYN('Project Already Present','Project already loaded, delete unsaved data?')
                     app.logDBG("Project Present - Dismiss");
                    return
                end
                app.logDBG("Project Present - Continue");
            end
            filter = {'*.mat','MATLAB Files (*.mat)'};
            title = 'Select a NEW File';
            defname = 'FINGER_ID.mat';
            [file,path,indx] = uiputfile(filter,title,defname); %#ok<ASGLU> 
            if file
                full_path = [path file];
                app.logINFO(['New File Selected ' full_path]);
                app.newProject(full_path);
            end

        end

        % Menu selected function: LoadMenu
        function LoadMenuSelected(app, event)
            %File->Load...
            % Ask for the new file location
            app.logDBG("LoadMenuSelected...");
            if ~isempty(app.projectData)
                app.logDBG("Project Present");
                if ~app.GUI_displayWarnYN('Project Already Present','Project already loaded, delete unsaved data?')
                     app.logDBG("Project Present - Dismiss");
                    return
                end
                app.logDBG("Project Present - Continue");
            end
            filter = {'*.mat','MATLAB Files (*.mat)'};
            title = 'Select a project file File';
            defname = 'FINGER_ID.mat';
            [file,path,indx] = uigetfile(filter,title,defname); %#ok<ASGLU> 
            if file
                full_path = [path file];
                app.logINFO(['File Selected ' full_path]);
                app.loadProject(full_path);
            end
        end

        % Menu selected function: initROSMenu
        function initROSMenuSelected(app, event)
            app.logDBG('initROSMenuSelected...')

            if isempty(app.projectData)
                app.logERR('load/create a project first')
                app.GUI_displayWarn('ERROR', 'load/create a project first')
                return
            end

            try
                switch app.projectData.gui_data.calib_mode
                    case 0
                        app.logERR('mode NONE')
                        app.GUI_displayWarn('ERROR', 'mode NONE')
                        return
                    case 1
                        app.logINFO('mode HAND')
                        app.GUI_displayWarn('ERROR', 'MODE HAND NOT IMPLEMENTED!')
                        return
                    case 2
                        app.logINFO('mode ROBOT')
                        app.GUI_displayWarn('INFO', 'MODE ROBOT!')
                        app.ROS_init_mode_robot()
                    otherwise
                        app.logERR(['Invalid calibration mode!' num2str(app.projectData.gui_data.calib_mode)])
                        app.GUI_displayWarn('ERROR', ['Invalid calibration mode!' num2str(app.projectData.gui_data.calib_mode)])
                        return
                end
                app.GUI_displayWarn('ROS INIT','Ros Init OK')
                app.logDBG('initROSMenuSelected END')

            catch ME
                switch ME.identifier
                    case 'ros:mlros:serviceclient:ConnectWaitTimeout'
                        app.GUI_displayWarn('ERROR', 'Timeout In Init ROS')
                        app.ROS_clear();
                    otherwise
                        rethrow(ME)
                end
            end


        end

        % Menu selected function: stopROSMenu
        function stopROSMenuSelected(app, event)
            app.logDBG('Stopping ROS...')
            app.ROS_clear();
            app.logDBG('Stopping DONE!')
            app.GUI_displayWarn('INFO', 'ROS STOPPED')
        end

        % Value changed function: dropDown_fn_interval, 
        % dropDown_zone, slider_plot_radius
        function slider_plot_radiusValueChanged(app, event)
            app.GUI_refreshMinimal();
        end

        % Button pushed function: ABORTButton
        function ABORTButtonPushed(app, event)
            app.F_abort();
        end

        % Menu selected function: SavewithNameMenu
        function SavewithNameMenuSelected(app, event)
            filter = {'*.mat','MATLAB Files (*.mat)'};
            title = 'Save project';
            defname = [ app.projectData.finger_info.finger_id '.mat'];
            [file,path,indx] = uiputfile(filter,title,defname); %#ok<ASGLU> 
            if file
                full_path = [path file];
                app.logDBG(['File Selected ' full_path]);
                app.saveProject(full_path);
                app.GUI_displayWarn('Save ok',['saved on ' app.project_path], true);
            end
        end

        % Callback function: GUI_refresh_minimalMenu, RefreshGUIButton
        function GUI_refresh_minimalMenuSelected(app, event)
            app.GUI_refreshMinimal();
        end

        % Menu selected function: SaveMenu
        function SaveMenuSelected(app, event)
            app.saveProject();
            app.GUI_displayWarn('Save ok',['saved on ' app.project_path], true);
        end
    end

    % Component initialization
    methods (Access = private)

        % Create UIFigure and components
        function createComponents(app)

            % Create FingerCalibrationUIFigure and hide until all components are created
            app.FingerCalibrationUIFigure = uifigure('Visible', 'off');
            app.FingerCalibrationUIFigure.Position = [100 100 960 540];
            app.FingerCalibrationUIFigure.Name = 'Finger Calibration';
            app.FingerCalibrationUIFigure.CloseRequestFcn = createCallbackFcn(app, @FingerCalibrationUIFigureCloseRequest, true);

            % Create FileMenu
            app.FileMenu = uimenu(app.FingerCalibrationUIFigure);
            app.FileMenu.Text = 'File';

            % Create NewMenu
            app.NewMenu = uimenu(app.FileMenu);
            app.NewMenu.MenuSelectedFcn = createCallbackFcn(app, @NewMenuSelected, true);
            app.NewMenu.Text = 'New';

            % Create SaveMenu
            app.SaveMenu = uimenu(app.FileMenu);
            app.SaveMenu.MenuSelectedFcn = createCallbackFcn(app, @SaveMenuSelected, true);
            app.SaveMenu.Text = 'Save';

            % Create SavewithNameMenu
            app.SavewithNameMenu = uimenu(app.FileMenu);
            app.SavewithNameMenu.MenuSelectedFcn = createCallbackFcn(app, @SavewithNameMenuSelected, true);
            app.SavewithNameMenu.Text = 'Save with Name...';

            % Create LoadMenu
            app.LoadMenu = uimenu(app.FileMenu);
            app.LoadMenu.MenuSelectedFcn = createCallbackFcn(app, @LoadMenuSelected, true);
            app.LoadMenu.Text = 'Load...';

            % Create ToolMenu
            app.ToolMenu = uimenu(app.FingerCalibrationUIFigure);
            app.ToolMenu.Text = 'Tool';

            % Create ROSMenu
            app.ROSMenu = uimenu(app.ToolMenu);
            app.ROSMenu.Text = 'ROS';

            % Create initROSMenu
            app.initROSMenu = uimenu(app.ROSMenu);
            app.initROSMenu.MenuSelectedFcn = createCallbackFcn(app, @initROSMenuSelected, true);
            app.initROSMenu.Text = 'init ROS';

            % Create stopROSMenu
            app.stopROSMenu = uimenu(app.ROSMenu);
            app.stopROSMenu.MenuSelectedFcn = createCallbackFcn(app, @stopROSMenuSelected, true);
            app.stopROSMenu.Text = 'stop ROS';

            % Create DBGMenu
            app.DBGMenu = uimenu(app.ToolMenu);
            app.DBGMenu.Text = 'DBG';

            % Create GUI_refresh_minimalMenu
            app.GUI_refresh_minimalMenu = uimenu(app.DBGMenu);
            app.GUI_refresh_minimalMenu.MenuSelectedFcn = createCallbackFcn(app, @GUI_refresh_minimalMenuSelected, true);
            app.GUI_refresh_minimalMenu.Text = 'GUI_refresh_minimal';

            % Create gridLayout_main_grid
            app.gridLayout_main_grid = uigridlayout(app.FingerCalibrationUIFigure);
            app.gridLayout_main_grid.ColumnWidth = {'2x', '1x'};
            app.gridLayout_main_grid.RowHeight = {'1x'};

            % Create GridLayout2
            app.GridLayout2 = uigridlayout(app.gridLayout_main_grid);
            app.GridLayout2.Padding = [0 0 0 0];
            app.GridLayout2.Layout.Row = 1;
            app.GridLayout2.Layout.Column = 1;

            % Create Panel_ax_fxfy
            app.Panel_ax_fxfy = uipanel(app.GridLayout2);
            app.Panel_ax_fxfy.Layout.Row = 1;
            app.Panel_ax_fxfy.Layout.Column = 1;

            % Create GridLayout_ax_fxfy
            app.GridLayout_ax_fxfy = uigridlayout(app.Panel_ax_fxfy);
            app.GridLayout_ax_fxfy.ColumnWidth = {'1x'};
            app.GridLayout_ax_fxfy.RowHeight = {'1x'};

            % Create axes_fx_fy
            app.axes_fx_fy = uiaxes(app.GridLayout_ax_fxfy);
            title(app.axes_fx_fy, '')
            xlabel(app.axes_fx_fy, 'f_x')
            ylabel(app.axes_fx_fy, 'f_y')
            app.axes_fx_fy.Layout.Row = 1;
            app.axes_fx_fy.Layout.Column = 1;

            % Create Panel_ax_fxtau
            app.Panel_ax_fxtau = uipanel(app.GridLayout2);
            app.Panel_ax_fxtau.Layout.Row = 1;
            app.Panel_ax_fxtau.Layout.Column = 2;

            % Create GridLayout_ax_fxtau
